from pathlib import Path
import base64,hashlib,json,lzma,os,re

root=Path(os.environ['SOURCE_ROOT']).resolve()
updater=root/'src'/'MerzoOptimizer.Windows'/'Updates'/'GitHubUpdateService.cs'
expected='046f883dbbbcdac5a3ed1a674f7c2f87c36c07a0dfb2d9b6de73cd9fa566434a'
actual=hashlib.sha256(updater.read_bytes()).hexdigest()
if actual!=expected:
    raise SystemExit(f'R48 updater baseline mismatch: {actual}')

payload=''''''
new_bytes=lzma.decompress(base64.b64decode(payload))
if hashlib.sha256(new_bytes).hexdigest()!='836cb4c90b787c7601032ed657584b28b9c170a6ead413f8427bc96d9faf3bb3':
    raise SystemExit('R48 updater payload hash mismatch')
updater.write_bytes(new_bytes)

# Stamp all primary projects to 0.1.48.0 / 0.1.48.
for p in (root/'src').rglob('*.csproj'):
    s=p.read_text(encoding='utf-8-sig')
    s=s.replace('<Version>0.1.47</Version>','<Version>0.1.48</Version>')
    s=s.replace('<VersionPrefix>0.1.47</VersionPrefix>','<VersionPrefix>0.1.48</VersionPrefix>')
    s=s.replace('<AssemblyVersion>0.1.47.0</AssemblyVersion>','<AssemblyVersion>0.1.48.0</AssemblyVersion>')
    s=s.replace('<FileVersion>0.1.47.0</FileVersion>','<FileVersion>0.1.48.0</FileVersion>')
    s=s.replace('<InformationalVersion>0.1.47</InformationalVersion>','<InformationalVersion>0.1.48</InformationalVersion>')
    p.write_text(s,encoding='utf-8')

xaml=root/'src'/'MerzoOptimizer.App'/'MainWindow.xaml'
x=xaml.read_text(encoding='utf-8-sig')
x=x.replace('Production 0.1.47 · R47 SIMPLE BUILDS','Production 0.1.48 · R48 OTA RELIABILITY')
x=x.replace('Production R47 · 0.1.47','Production R48 · 0.1.48')
x=x.replace('Text="R47" Foreground="{StaticResource Accent}"','Text="R48" Foreground="{StaticResource Accent}"',1)
xaml.write_text(x,encoding='utf-8')

selftest=root/'src'/'MerzoOptimizer.SelfTest'/'Program.cs'
ss=selftest.read_text(encoding='utf-8-sig')
ss=re.sub(r'Merzo Windows Optimizer — PRODUCTION R\d+[^"\r\n]*SelfTest','Merzo Windows Optimizer — PRODUCTION R48 OTA RELIABILITY SelfTest',ss)
selftest.write_text(ss,encoding='utf-8')

notes=root/'data'/'release_notes.json'
obj=json.loads(notes.read_text(encoding='utf-8-sig'))
obj['version']='0.1.48'
obj['title']='R48 OTA RELIABILITY'
obj['summary']='Надёжное обновление с retry и резервными GitHub API путями; исправляет 504 Gateway Timeout в старом update flow.'
obj['changes']=[
 'Update check автоматически повторяет временные 408/429/500/502/503/504 и timeout.',
 'Если общий releases endpoint недоступен, Merzo ищет только mwo-v* tags и запрашивает точный release-by-tag.',
 'Второй fallback использует lightweight tags endpoint; все пути остаются внутри официального Merzo4/my-app-updates.',
 'Проверки R46 security сохранены: exact installer name, official release URL, size, GitHub SHA-256 digest + SHA sidecar.',
 'Интерфейс трёх сборок R47 и Snapshot/Verify/Undo не изменены.'
]
notes.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(root/'R48_OTA_RELIABILITY.marker').write_text('R48 OTA RELIABILITY\n',encoding='utf-8')

final=updater.read_text(encoding='utf-8')
for token in ['ResolveBestReleaseAsync','GetJsonWithRetryAsync','matching-refs/tags','releases/tags/','HttpStatusCode.GatewayTimeout','TimeSpan.FromSeconds(45)','OfficialInstallerName','FixedTimeShaEquals']:
    if token not in final: raise SystemExit('R48 updater missing '+token)
print('R48 OTA reliability patch: OK')
